var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Bewerk de KlipperScreen-touchscreenconfiguratie van je printer veilig en herstart KlipperScreen om toe te passen. Bij elke opslag wordt er eerst een back-up gemaakt.`}},selector:{title:{t:0,b:{t:2,i:[{t:3}],s:`Touchscreen`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Kies welke interface op het scherm van de printer draait.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Vernieuwen`}},active:{t:0,b:{t:2,i:[{t:3}],s:`Actief`}},boot:{t:0,b:{t:2,i:[{t:3}],s:`Bij opstarten`}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Niet geïnstalleerd`}},use:{t:0,b:{t:2,i:[{t:3}],s:`Gebruiken`}},switching:{t:0,b:{t:2,i:[{t:3}],s:`Wisselen…`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Maak dit ook de standaard bij het opstarten`}}},touchPanel:{title:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind-bediening`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Voer FilaMinds controles en tests rechtstreeks vanaf het scherm uit.`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Help`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Over KlipperScreen Studio`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Sluiten`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Hoe te lezen`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Bewerk de configuratietekst hieronder (of laat hem ongewijzigd).`}},{t:0,b:{t:2,i:[{t:3}],s:`Opslaan - van het huidige bestand wordt eerst een back-up gemaakt, en opslaan wordt geweigerd zolang de printer bezig is.`}},{t:0,b:{t:2,i:[{t:3}],s:`Herstart KlipperScreen om de wijziging op het fysieke scherm toe te passen.`}},{t:0,b:{t:2,i:[{t:3}],s:`Regels gebruiken UNIX (LF) regeleinden, automatisch afgedwongen bij opslaan.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Woordenlijst`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Korte definities van de hier gebruikte KlipperScreen-termen.`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wat is het tabblad Config?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`De ruwe KlipperScreen.conf. Bewerk elke instelling met de hand; bij opslaan wordt eerst een back-up gemaakt, wordt geweigerd zolang de printer bezig is, en wordt gewaarschuwd als het bestand op het scherm is gewijzigd sinds je het hebt geladen. De meeste mensen gebruiken in plaats daarvan de tabbladen Instellingen / Menu's / Thema's.`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wat is het tabblad Instellingen?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`De meestgebruikte [main]-opties als formulier - thema, taal, schermslaap, tekengrootte en schakelaars. Vooraf ingevuld vanuit de live config; alleen de opties die je wijzigt worden weggeschreven. Herstart om toe te passen.`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wat is het tabblad Menu's?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Ontwerp de knoppenrasters van het touchscreen. Elke boom (__main is het startraster, __print het printscherm) toont zijn knoppen; voeg ze toe, hernoem, herorden en nest ze, en stel elke knop in om een submenu te openen, een ingebouwd scherm te openen of G-code uit te voeren.`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wat is het tabblad Thema's?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Bouw een KlipperScreen-thema: kies een kleur per palettoken en een hoekradius, bekijk de live preview en maak het thema aan om het op het scherm toe te passen. De preview is bij benadering - het echte scherm wordt met GTK weergegeven.`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`Wat is het tabblad Kiosk?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Zet FilaMind Flow zelf op het touchscreen als fullscreen browser - volledige controle over wat het scherm toont. Het is een omkeerbare wissel met KlipperScreen (standaard tijdelijk; een herstart herstelt KlipperScreen). Vereist het eenmalige installatieprogramma op de printerhost.`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`De touchscreen-UI die draait op een klein display aan de printer - los van dit webpaneel.`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`Thema`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een KlipperScreen-uiterlijk - kleuren, pictogrammen en hoekradius. Staat in een map styles/<name> op de host; alleen cosmetisch (kan de lay-out niet wijzigen).`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`Menu (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`De knoppenrasters die KlipperScreen toont. __main is het startscherm, __print het scherm dat tijdens het printen wordt getoond, __splashscreen het opstartscherm.`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`Paneel`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een ingebouwd KlipperScreen-scherm dat een knop kan openen (bewegen, temperatuur, extruderen, bed mesh, …). De interne inhoud ervan ligt vast in KlipperScreen.`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`Automatisch gegenereerd blok (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Het deel dat KlipperScreen voor zichzelf onderaan de conf schrijft, na de #~#-markering. FilaMind bewerkt dit nooit - alleen jouw instellingen erboven.`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een fullscreen browser op het touchscreen draaien in plaats van KlipperScreen, zodat het scherm FilaMind Flow toont. Volledig omkeerbaar.`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`Controleren op KlipperScreen…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen is niet op deze printer gedetecteerd (geen KlipperScreen.conf, en niet gemeld door Moonraker). Installeer KlipperScreen om deze tool te gebruiken.`}},present:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen gedetecteerd`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`Thema`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Taal`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker kan KlipperScreen niet automatisch herstarten - herstart het handmatig na het opslaan.`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf lezen…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`Opnieuw laden`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Config opslaan`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Opslaan…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`Opgeslagen (back-up gemaakt)`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Niet-opgeslagen wijzigingen`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`Geweigerd zolang de printer bezig is - probeer opnieuw wanneer hij inactief is.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf is op schijf gewijzigd sinds het laden (waarschijnlijk op het scherm bewerkt). Laad opnieuw vóór het opslaan zodat je die wijziging niet overschrijft.`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`Config`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Instellingen`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`Menu's`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`Thema's`}},kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},fmscreen:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind-scherm`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Instellingen laden…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`De meestgebruikte KlipperScreen-weergaveopties als formulier. Alleen de opties die je wijzigt worden weggeschreven - al het andere behoudt zijn huidige waarde. Herstart om toe te passen.`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`Alleen de instellingen die je hier wijzigt worden naar KlipperScreen.conf geschreven.`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Instellingen opslaan`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Opgeslagen - herstart KlipperScreen om toe te passen.`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`Niet instellen (standaard)`}},never:{t:0,b:{t:2,i:[{t:3}],s:`Nooit (altijd aan)`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`Klein`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`Middel`}},large:{t:0,b:{t:2,i:[{t:3}],s:`Groot`}},max:{t:0,b:{t:2,i:[{t:3}],s:`Max`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`Thema`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Taal`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`Schermslaap na`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`Tekengrootte`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`24-uursklok`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`DPMS gebruiken om het scherm uit te schakelen`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`Muisaanwijzer tonen`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`Bevestigen vóór noodstop`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`Verwarmervermogen % tonen`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`Pop-ups automatisch sluiten`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Het scherm controleren…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Zet FilaMind Flow zelf op het touchscreen als fullscreen browser - volledige controle over wat het scherm toont. Het wisselt met KlipperScreen: de een starten stopt de ander.`}},current:{t:0,b:{t:2,i:[{t:3}],s:`Scherm nu`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind-kiosk`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Geen van beide actief`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk nog niet geïnstalleerd`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`Voer dit eenmalig uit op de printerhost (installeert een fullscreen browser + de kioskservice):`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Maak het de standaard bij opstarten (anders is de wissel tijdelijk - een herstart herstelt de ander).`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`Standaard tijdelijk: een herstart brengt de ander terug. Als het scherm ooit zwart wordt, voer via SSH uit: sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Overschakelen naar FilaMind`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen herstellen`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Vernieuwen`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind op het scherm zetten?`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen herstellen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Dit stopt de ene schermservice en start de andere. Het beïnvloedt geen actieve print, maar het touchscreen wordt enkele seconden zwart tijdens het wisselen.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Doen`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annuleren`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind neemt het scherm over - het zou binnen enkele seconden moeten verschijnen.`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen komt terug - het scherm zou kort moeten terugkeren.`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Menu's laden…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Ontwerp wat het touchscreen toont: de knoppen van elk menu, hun volgorde en wat elke doet. Het startschermraster is de __main-boom; het printscherm is __print.`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`Knop toevoegen`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Nog geen items - voeg er een toe.`}},up:{t:0,b:{t:2,i:[{t:3}],s:`Omhoog`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Omlaag`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`Subitem toevoegen`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Verwijderen`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Naam`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`Pictogram`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Actie`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`Een submenu openen`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`Een scherm openen`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code uitvoeren`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`Scherm`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Tonen als`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Menu's opslaan`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`Nieuwe knop`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Menu's opgeslagen - herstart KlipperScreen om ze te zien.`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Thema's laden…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`Palet`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`Hoekradius`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`Live voorbeeld`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`Knop`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`waarschuwing`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`Benaderende preview - het echte scherm wordt met GTK weergegeven; kleine verschillen zijn te verwachten.`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Naam nieuw thema`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`Aanmaken en toepassen`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`Alleen aanmaken`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`Geïnstalleerde thema's`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Toepassen`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Thema verwijderen`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`Hier gemaakt`}},created:{t:0,b:{t:2,i:[{t:3}],s:`Thema aangemaakt. Pas het toe vanuit de lijst en herstart daarna.`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Thema ingesteld - herstart KlipperScreen om het te zien.`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`Printer`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen herstarten`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Herstarten…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen wordt herstart - het scherm laadt kort opnieuw.`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen herstarten?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Dit herstart de touchscreenservice om je wijzigingen toe te passen. Het beïnvloedt geen actieve print, maar het scherm wordt enkele seconden zwart.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Herstarten`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annuleren`}}}}};export{e as default};